"""Compact observation-driven temporal controller for safe target approach."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or collision risk reaches the hard limit."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Use one verification pause, then hold a scan direction during reacquisition."""
    reliable = (
        bool(observation["target_visible"])
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )
    if not reliable:
        lost_steps = int(observation["lost_steps"])
        if memory.get("state") in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} and lost_steps <= 1:
            memory["state"] = "REACQUIRE"
            return "STOP", 0.92
        if lost_steps == 0 or "scan_direction" not in memory:
            memory["scan_direction"] = memory.get("scan_direction", "SCAN_LEFT")
        elif lost_steps % 3 == 0:
            memory["scan_direction"] = (
                "SCAN_RIGHT"
                if memory["scan_direction"] == "SCAN_LEFT"
                else "SCAN_LEFT"
            )
        memory["state"] = "SEARCH"
        return memory["scan_direction"], 0.75

    if int(observation["track_age"]) < 2 and not memory.get("verified_once", False):
        memory["verified_once"] = True
        memory["state"] = "VERIFY"
        return "SLOW_DOWN", 0.80

    memory["verified_once"] = False
    return None


def propose_moves(observation, memory):
    """Order corridor motions by bearing while retaining only observable choices."""
    bearing = float(observation["target_bearing"])
    choices = []
    if bearing < -12.0 and observation["corridor_left"]:
        choices.append("VEER_LEFT")
    elif bearing > 12.0 and observation["corridor_right"]:
        choices.append("VEER_RIGHT")
    if observation["corridor_center"]:
        choices.append("FORWARD")
    if observation["corridor_left"]:
        choices.append("VEER_LEFT")
    if observation["corridor_right"]:
        choices.append("VEER_RIGHT")

    unique = list(dict.fromkeys(choices))
    previous = memory.get("last_action")
    opposite = {"VEER_LEFT": "VEER_RIGHT", "VEER_RIGHT": "VEER_LEFT"}
    if previous in opposite and opposite[previous] in unique and "FORWARD" in unique:
        unique.remove(opposite[previous])
    return unique


def progress_contract(observation, memory, candidates):
    """Prefer forward progress and suppress immediate steering reversals."""
    if not candidates:
        return None
    previous = memory.get("last_action")
    if previous in candidates and len(candidates) > 1:
        if previous == "FORWARD":
            return "FORWARD"
        bearing = float(observation["target_bearing"])
        preferred = "VEER_LEFT" if bearing < -12.0 else "VEER_RIGHT" if bearing > 12.0 else "FORWARD"
        if preferred in candidates:
            return preferred
    return candidates[0]


def termination_contract(observation, memory):
    """Return a safe stationary action when no motion proposal is admissible."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Apply safety, tracking, arrival, and progress contracts in fixed priority order."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        memory["last_action"] = safety[0]
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        memory["last_action"] = tracking[0]
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        if (
            abs(float(observation["heading_error"])) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        ):
            memory["state"] = "ARRIVED"
            memory["last_action"] = "ARRIVED"
            return "ARRIVED", 0.96, memory
        candidates = [
            "VEER_LEFT"
            if float(observation["target_bearing"]) < 0.0
            else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        memory["last_action"] = fallback[0]
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    memory["last_action"] = action
    return action, 0.90, memory


# EVOLVE-BLOCK-END
